from sys import setrecursionlimit
setrecursionlimit(10 ** 9)

def dfs(p, prev, turn):
	(m1, m2) = (float('inf'), -float('inf'))
	for i in child[p]:
		if i == prev:
			continue
		x = dfs(i, p, turn ^ 1)
		m1 = min(m1, x + a[p - 1])
		m2 = max(m2, x + a[p - 1])
	if p != 1 and len(child[p]) == 1 or len(child[p]) == 0:
		return a[p - 1]
	else:
		return m2 if turn else m1
